@pytest.mark.django_db
def test_validate_memberships_expired(event, customer, membership, requiring_ticket):
    membership.date_end = datetime(2021, 4, 10, 23, 59, 59, 999999, tzinfo=TZ)
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_membership_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_valid_from_not_chosen(event, customer, membership, requiring_ticket):
    # Starts in the future, so not valid for the event date, but it has not ended yet
    membership.date_start = now() + timedelta(days=10)
    membership.date_end = now() + timedelta(days=40)
    membership.save()
    p = _membership_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [p], event)
    validate_memberships_in_order(customer, [p], event, valid_from_not_chosen=True)


@pytest.mark.django_db
def test_validate_memberships_testmode(event, customer, membership, requiring_ticket):
    membership.testmode = True
    membership.save()
    p = _membership_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [p], event, testmode=False)
    validate_memberships_in_order(customer, [p], event, testmode=True)


@pytest.mark.django_db
def test_validate_memberships_max_usages_in_same_purchase(event, customer, membership, requiring_ticket):
    membership.membership_type.max_usages = 1
    membership.membership_type.save()
    positions = [
        _membership_position(event, requiring_ticket, membership),
        _membership_position(event, requiring_ticket, membership),
    ]
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, positions, event)
    assert 'maximum number of times' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_max_usages_existing_order(event, customer, membership, requiring_ticket):
    membership.membership_type.max_usages = 1
    membership.membership_type.save()
    order = Order.objects.create(event=event, status=Order.STATUS_PAID, expires=now() + timedelta(days=3),
                                 sales_channel=event.organizer.sales_channels.get(identifier="web"), total=23)
    OrderPosition.objects.create(order=order, item=requiring_ticket, price=23, used_membership=membership)
    p = _membership_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [p], event)
    # The order that is being changed does not count against its own usage
    validate_memberships_in_order(customer, [p], event, ignored_order=order)


@pytest.mark.django_db
def test_validate_memberships_parallel_usage(event, customer, membership, requiring_ticket):
    positions = [
        _membership_position(event, requiring_ticket, membership),
        _membership_position(event, requiring_ticket, membership),
    ]
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, positions, event)
    assert 'multiple products at the same time' in excinfo.value.message

    membership.membership_type.allow_parallel_usage = True
    membership.membership_type.save()
    validate_memberships_in_order(customer, positions, event)


@pytest.mark.django_db
def test_validate_memberships_parallel_usage_existing_order(event, customer, membership, requiring_ticket):
    order = Order.objects.create(event=event, status=Order.STATUS_PAID, expires=now() + timedelta(days=3),
                                 sales_channel=event.organizer.sales_channels.get(identifier="web"), total=23)
    OrderPosition.objects.create(order=order, item=requiring_ticket, price=23, used_membership=membership)
    p = _membership_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [p], event)
    validate_memberships_in_order(customer, [p], event, ignored_order=order)


@pytest.mark.django_db
def test_validate_memberships_not_transferable(event, customer, membership, requiring_ticket):
    membership.attendee_name_parts = {'full_name': 'John Doe'}
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [
            _membership_position(event, requiring_ticket, membership, attendee_name_parts={'full_name': 'Jane'})
        ], event)
    validate_memberships_in_order(customer, [
        _membership_position(event, requiring_ticket, membership, attendee_name_parts={'full_name': 'John Doe'})
    ], event)


